import { useEffect, useMemo, useRef, useState } from 'react';
import { Activity, Archive, ArrowDownToLine, BarChart3, Bell, Check, ChevronDown, CircleHelp, CreditCard, Ellipsis, FileText, Filter, Package, Plus, Search, Settings, ShoppingBag, ShoppingCart, Store, Tag, Truck, Users, Wallet, X } from 'lucide-react';

const money = n => new Intl.NumberFormat('es-AR',{style:'currency',currency:'ARS',maximumFractionDigits:2}).format(Number(n)||0);
const roundMoney = n => Math.round((Number(n)+Number.EPSILON)*100)/100;
const pendingWrites = new Map();
const skuError = (sku, variants, products, productId) => {
  const norm=value=>String(value||'').trim().toLocaleLowerCase('es-AR');
  const productSku=norm(sku);
  for(const product of products.filter(item=>item.id!==productId)){
    if(norm(product.sku)===productSku) return 'Ya existe un producto con ese código.';
    if((product.variants||[]).some(variant=>variant.sku&&norm(variant.sku)===productSku)) return 'El código ya está asignado a una variante.';
  }
  const seen=new Set();
  for(const variant of variants){
    if(!String(variant.name||'').trim()) return 'Cada variante necesita un nombre.';
    const stock=Number(variant.stock);
    if(!Number.isFinite(stock)||stock<0) return `El stock de ${variant.name} debe ser un número igual o mayor a cero.`;
    const code=norm(variant.sku);
    if(!code) continue;
    if(code===productSku) return 'El SKU del producto y el de sus variantes deben ser distintos.';
    if(seen.has(code)) return `El código de variante ${variant.sku} está repetido.`;
    seen.add(code);
    for(const product of products){
      if(norm(product.sku)===code) return `El código de variante ${variant.sku} ya pertenece al producto ${product.name}.`;
      if(product.id!==productId&&(product.variants||[]).some(other=>other.sku&&norm(other.sku)===code)) return `El código de variante ${variant.sku} ya está asignado.`;
    }
  }
  return '';
};
const api = async (path, options={}) => {
  const method=(options.method||'GET').toUpperCase(),key=method==='GET'?null:`${method}:${path}:${options.body||''}`;
  if(key&&pendingWrites.has(key))return pendingWrites.get(key);
  const request=(async()=>{const res=await fetch('/api'+path,{headers:{'Content-Type':'application/json'},...options});const data=await res.json();if(res.status===401&&!path.startsWith('/auth/'))window.dispatchEvent(new Event('kiosco:auth-expired'));if(!res.ok)throw new Error(data.error||'Ocurrió un error.');return data;})();
  if(!key)return request;
  pendingWrites.set(key,request);
  try{return await request}finally{if(pendingWrites.get(key)===request)pendingWrites.delete(key)}
};
const nav = [
  {group:'OPERACIÓN',items:[['Punto de venta',ShoppingCart],['Compras',ShoppingBag]]},
  {group:'CATÁLOGO',items:[['Productos',Package],['Inventario',Archive]]},
  {group:'PERSONAS',items:[['Clientes',Users],['Usuarios',Users]]},
  {group:'ANÁLISIS',items:[['Reportes',BarChart3],['Historial de ventas',FileText],['Historial de caja',Wallet]]},
  {group:'SISTEMA',items:[['Configuración',Settings]]},
];

function AuthScreen({mode,complete}){
  const[form,setForm]=useState({name:'',email:'',password:''}),[error,setError]=useState(''),[busy,setBusy]=useState(false);
  const setup=mode==='setup';
  const submit=async event=>{event.preventDefault();setBusy(true);setError('');try{await api(setup?'/auth/setup':'/auth/login',{method:'POST',body:JSON.stringify(form)});await complete()}catch(e){setError(e.message)}finally{setBusy(false)}};
  return <div className="auth-screen"><form className="auth-card" onSubmit={submit}><div className="brand-mark">K</div><div className="eyebrow">{setup?'PRIMER ACCESO':'ACCESO AL KIOSCO'}</div><h1>{setup?'Configurá el administrador':'Iniciar sesión'}</h1><p>{setup?'Asigná las credenciales del administrador existente para proteger este kiosco.':'Ingresá con tu usuario para continuar.'}</p>{setup&&<label>Nombre<input autoComplete="name" value={form.name} onChange={e=>setForm({...form,name:e.target.value})} required minLength="2" maxLength="80"/></label>}<label>Email<input type="email" autoComplete="username" value={form.email} onChange={e=>setForm({...form,email:e.target.value})} required/></label><label>Contraseña<input type="password" autoComplete={setup?'new-password':'current-password'} value={form.password} onChange={e=>setForm({...form,password:e.target.value})} required minLength={setup?10:1}/></label>{setup&&<small className="field-hint">Usá al menos 10 caracteres. La contraseña se almacena cifrada con derivación segura.</small>}{error&&<div className="form-error">{error}</div>}<button className="button primary full" disabled={busy}>{busy?'Validando…':setup?'Guardar y entrar':'Entrar'}</button></form></div>;
}

function UsersManagement({notify}){
  const[users,setUsers]=useState([]),[form,setForm]=useState({name:'',email:'',password:'',role:'employee'}),[editing,setEditing]=useState(null),[error,setError]=useState('');
  const load=()=>api('/users').then(setUsers).catch(e=>setError(e.message));useEffect(()=>{load()},[]);
  const create=async event=>{event.preventDefault();setError('');try{await api('/users',{method:'POST',body:JSON.stringify(form)});setForm({name:'',email:'',password:'',role:'employee'});await load();notify('Usuario creado.')}catch(e){setError(e.message)}};
  const save=async event=>{event.preventDefault();setError('');try{await api(`/users/${editing.id}`,{method:'PATCH',body:JSON.stringify(editing)});setEditing(null);await load();notify('Usuario actualizado.')}catch(e){setError(e.message)}};
  const row=(user)=> <tr key={user.id}><td><b>{user.name}</b></td><td>{user.email}</td><td>{user.role==='admin'?'Administrador':'Empleado'}</td><td><span className={`status-pill ${user.active?'':'closed'}`}>{user.active?'Activo':'Inactivo'}</span></td><td><button className="button tiny" onClick={()=>{setEditing({...user,password:''});setError('')}}>Editar</button></td></tr>;
  return <div className="management-grid"><section className="panel table-panel"><div className="panel-heading"><div><h2>Usuarios</h2><p>Las contraseñas nunca se muestran.</p></div></div><div className="table-wrap"><table><thead><tr><th>NOMBRE</th><th>EMAIL</th><th>ROL</th><th>ESTADO</th><th></th></tr></thead><tbody>{users.map(row)}</tbody></table>{error&&<div className="form-error">{error}</div>}</div></section><form className="panel management-form" onSubmit={create}><h2>Crear usuario</h2><p>El acceso queda asociado a este kiosco.</p><label>Nombre<input value={form.name} onChange={e=>setForm({...form,name:e.target.value})} required minLength="2" maxLength="80"/></label><label>Email<input type="email" value={form.email} onChange={e=>setForm({...form,email:e.target.value})} required/></label><label>Contraseña inicial<input type="password" value={form.password} onChange={e=>setForm({...form,password:e.target.value})} required minLength="10"/></label><label>Rol<select value={form.role} onChange={e=>setForm({...form,role:e.target.value})}><option value="employee">Empleado</option><option value="admin">Administrador</option></select></label><button className="button primary">Crear usuario</button></form>{editing&&<div className="modal-backdrop" onMouseDown={()=>setEditing(null)}><form className="modal compact-modal management-form" onSubmit={save} onMouseDown={e=>e.stopPropagation()}><div className="modal-header"><div><h2>Editar usuario</h2><p>Dejá la contraseña vacía para conservarla.</p></div><button type="button" className="icon-button" onClick={()=>setEditing(null)}><X size={20}/></button></div><div className="modal-body"><label>Nombre<input value={editing.name} onChange={e=>setEditing({...editing,name:e.target.value})} required minLength="2"/></label><label>Email<input type="email" value={editing.email} onChange={e=>setEditing({...editing,email:e.target.value})} required/></label><label>Nueva contraseña<input type="password" value={editing.password} onChange={e=>setEditing({...editing,password:e.target.value})} minLength={editing.password?10:undefined}/></label><label>Rol<select value={editing.role} onChange={e=>setEditing({...editing,role:e.target.value})}><option value="employee">Empleado</option><option value="admin">Administrador</option></select></label><label className="checkbox-label"><input type="checkbox" checked={Boolean(editing.active)} onChange={e=>setEditing({...editing,active:e.target.checked?1:0})}/> Usuario activo</label>{error&&<div className="form-error">{error}</div>}</div><div className="modal-footer"><button type="button" className="button secondary" onClick={()=>setEditing(null)}>Cancelar</button><button className="button primary">Guardar cambios</button></div></form></div>}</div>;
}

function SettingsManagement({settings,expiryDays,saved}){
  const[form,setForm]=useState({name:settings.name,expiry_alert_days:expiryDays}),[error,setError]=useState('');
  useEffect(()=>setForm({name:settings.name,expiry_alert_days:expiryDays}),[settings.name,expiryDays]);
  const submit=async event=>{event.preventDefault();setError('');try{await api('/settings',{method:'PATCH',body:JSON.stringify(form)});await saved()}catch(e){setError(e.message)}};
  return <form className="panel settings-form" onSubmit={submit}><div className="panel-heading"><div><h2>Configuración del kiosco</h2><p>Opciones que afectan directamente el sistema.</p></div></div><label>Nombre del kiosco<input value={form.name} onChange={e=>setForm({...form,name:e.target.value})} required minLength="2" maxLength="100"/></label><label>Días para alertar antes del vencimiento<input type="number" min="1" max="365" step="1" value={form.expiry_alert_days} onChange={e=>setForm({...form,expiry_alert_days:e.target.value})} required/><small className="field-hint">Se aplica a las alertas de productos y variantes con stock. El valor actual es {expiryDays} días.</small></label>{error&&<div className="form-error">{error}</div>}<button className="button primary">Guardar configuración</button></form>;
}

export default function App(){
  const [data,setData]=useState(null),[authMode,setAuthMode]=useState('loading'),[page,setPage]=useState('Productos'),[search,setSearch]=useState(''),[modal,setModal]=useState(''),[editing,setEditing]=useState(null),[toast,setToast]=useState(''),[cart,setCart]=useState([]),[cartSearch,setCartSearch]=useState(''),[customerId,setCustomerId]=useState(''),[ticket,setTicket]=useState(null),[purchaseRevision,setPurchaseRevision]=useState(0);
  const [filters,setFilters]=useState({status:'all',category:'all',stock:'all'}),[selectedIds,setSelectedIds]=useState([]),[pageNumber,setPageNumber]=useState(1);
  const searchRef=useRef(null);
  const refresh=async()=>setData(await api('/bootstrap'));
  const initialize=async()=>{try{const status=await api('/auth/status');if(status.setup_required){setAuthMode('setup');return}await api('/auth/me');await refresh();setAuthMode('ready')}catch{setAuthMode('login')}};
  useEffect(()=>{initialize()},[]);
  useEffect(()=>{const expired=()=>{setData(null);setAuthMode('login')};window.addEventListener('kiosco:auth-expired',expired);return()=>window.removeEventListener('kiosco:auth-expired',expired)},[]);
  const products=data?.products||[], categories=data?.categories||[], suppliers=data?.suppliers||[],customers=data?.customers||[];
  const filtered=useMemo(()=>products.filter(p=>`${p.name} ${p.sku}`.toLowerCase().includes(search.toLowerCase())&&(filters.status==='all'||(filters.status==='active'?Boolean(p.active):!p.active))&&(filters.category==='all'||p.category_id===filters.category)&&(filters.stock==='all'||(filters.stock==='low'?p.stock<=p.stock_alert:p.stock===0))),[products,search,filters]);
  const pageSize=10,pageCount=Math.max(1,Math.ceil(filtered.length/pageSize)),pageProducts=filtered.slice((pageNumber-1)*pageSize,pageNumber*pageSize);
  useEffect(()=>{setPageNumber(1);setSelectedIds([])},[search,filters]);
  useEffect(()=>{const onKeyDown=event=>{if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'&&page==='Productos'){event.preventDefault();searchRef.current?.focus()}if(event.key==='Escape'&&modal)setModal('')};window.addEventListener('keydown',onKeyDown);return()=>window.removeEventListener('keydown',onKeyDown)},[page,modal]);
  const notify=message=>{setToast(message);setTimeout(()=>setToast(''),3200)};
  const openProduct=p=>{setEditing(p||null);setModal('product')};
  const setBulkStatus=async active=>{try{for(const id of selectedIds)await api(`/products/${id}`,{method:'PATCH',body:JSON.stringify({active:active?1:0})});setSelectedIds([]);setModal('');await refresh();notify(`${selectedIds.length} producto(s) ${active?'activados':'desactivados'}.`)}catch(e){notify(e.message)}};
  const exportProducts=()=>{const fields=['name','sku','category_name','supplier_name','unit','cost','price','tax_rate','stock','stock_alert','expires_on','variant_expirations','expiry_status','active'];const value=(product,field)=>field==='variant_expirations'?(product.variants||[]).map(variant=>`${variant.name}: ${variant.expires_on||'sin fecha'}`).join(' | '):product[field];const escape=value=>`"${String(value??'').replaceAll('"','""')}"`;const csv=[fields.join(';'),...products.map(p=>fields.map(field=>escape(value(p,field))).join(';'))].join('\r\n');const url=URL.createObjectURL(new Blob(['\ufeff',csv],{type:'text/csv;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='productos-kiosco.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);setModal('');notify('Catálogo exportado en CSV.')};
  if(authMode==='loading')return <div className="loading"><div className="spinner"/>Preparando tu kiosco…</div>;
  if(authMode==='setup'||authMode==='login')return <AuthScreen mode={authMode} complete={async()=>{await refresh();setAuthMode('ready')}}/>;
  if(!data)return <div className="loading"><div className="spinner"/>Preparando tu kiosco…</div>;
  const isAdmin=data.user.role==='admin';
  const visibleNav=nav.map(section=>({...section,items:section.items.filter(([label])=>isAdmin||['Punto de venta','Productos','Inventario','Historial de ventas'].includes(label))})).filter(section=>section.items.length);
  const pageTitle=page==='Inventario'?'Inventario':page;
  const pageSubtitle={Productos:'Gestioná el catálogo y el stock de tu negocio',Inventario:'Controlá las existencias de tus productos','Punto de venta':'Registrá ventas y cobros de forma rápida',Compras:'Ingresá mercadería y mantené actualizado el inventario',Reportes:'Totales calculados sobre el período seleccionado','Historial de ventas':'Buscá y consultá tickets anteriores','Historial de caja':'Revisá sesiones, arqueos y movimientos anteriores'}[page]||'Administrá la información de tu negocio';
  const addCart=(p,variant=null)=>{const key=`${p.id}:${variant?.id||''}`;setCart(prev=>{const existing=prev.find(x=>x.key===key);return existing?prev.map(x=>x.key===key?{...x,quantity:x.quantity+1}:x):[...prev,{key,id:p.id,name:variant?`${p.name} · ${variant.name}`:p.name,sku:variant?.sku||p.sku,price:p.price,quantity:1,variant_id:variant?.id||null,available:variant?.stock??p.stock}]})};
  const finishSale=async(payments,selectedCustomer=customerId)=>{try{const result=await api('/sales',{method:'POST',body:JSON.stringify({items:cart,payments,customer_id:selectedCustomer||null})});setCart([]);await refresh();setTicket(result);setModal('ticket')}catch(e){notify(e.message)}};
  return <div className={`app-shell ${page==='Punto de venta'?'attendant-mode':''}`}>
    <aside className="sidebar">
      <div className="brand"><div className="brand-mark">K</div><div className="brand-copy"><strong>{data.tenant.name}</strong><span>Panel de gestión</span></div></div>
      <div className="nav-scroll">{visibleNav.map(section=><div className="nav-section" key={section.group}><div className="nav-label">{section.group}</div>{section.items.map(([label,Icon])=><button key={label} title={label} aria-label={label} className={`nav-item ${page===label?'selected':''}`} onClick={()=>setPage(label)}><Icon size={18}/><span>{label}</span></button>)}</div>)}</div>
      <div className="cash-card"><div className="cash-head"><Wallet size={17}/><b>Mi caja</b><span className={`status-pill ${data.cash?'':'closed'}`}>{data.cash?'Abierta':'Cerrada'}</span></div>{data.cash?<><div className="cash-detail">Efectivo esperado <b>{money(data.cash.expected_cash)}</b></div><button className="cash-button" aria-label="Gestionar caja" title="Gestionar caja" onClick={()=>setModal('cash')}>Gestionar caja</button></>:<><p>La caja está cerrada</p><button className="cash-button primary" aria-label="Abrir mi caja" title="Abrir mi caja" onClick={()=>setModal('open-cash')}>Abrir mi caja</button></>}</div>
      <div className="user-box"><div className="avatar">{data.user.name[0]}</div><div><b>{data.user.name}</b><span>{isAdmin?'Administrador':'Empleado'}</span></div><button className="logout-button" onClick={async()=>{await api('/auth/logout',{method:'POST'});setData(null);setAuthMode('login')}}>Salir</button></div>
    </aside>
    <main className="main-area">
      <header className="topbar"><div className="crumb"><span>{data.tenant.name}</span><span className="crumb-sep">/</span><b>{pageTitle}</b></div><div className="top-actions"><button className="icon-button" title="Notificaciones" aria-label="Notificaciones" onClick={()=>setModal('notifications')}><Bell size={18}/></button><button className="help-button" onClick={()=>setModal('help')}><CircleHelp size={16}/> Ayuda</button></div></header>
      <div className="content">
        <div className="page-heading"><div><div className="eyebrow">{page==='Productos'||page==='Inventario'?'CATÁLOGO':'MI NEGOCIO'}</div><h1>{pageTitle}</h1><p>{pageSubtitle}</p></div>{page==='Productos'&&isAdmin&&<div className="heading-actions"><button className="button secondary" onClick={()=>setModal('more')}><Ellipsis size={17}/> Más opciones <ChevronDown size={14}/></button><button className="button primary" onClick={()=>openProduct()}><Plus size={17}/> Nuevo producto</button></div>}{page==='Compras'&&<button className="button primary" onClick={()=>setModal('purchase')}><Plus size={17}/> Nueva compra</button>}</div>
        {page==='Productos'&&<>
          <div className="toolbar"><div className="searchbox"><Search size={18}/><input ref={searchRef} value={search} onChange={e=>setSearch(e.target.value)} placeholder="Buscar por nombre o código…"/><kbd>Ctrl K</kbd></div><button className="button secondary filter-btn" onClick={()=>setModal('filters')}><Filter size={16}/> Filtros{Object.values(filters).some(value=>value!=='all')&&<span className="filter-dot"/>}</button></div>
          <section className="panel table-panel"><div className="panel-heading"><div><h2>Productos</h2><p>{isAdmin?'Lista de todos los productos registrados':'Consulta de productos, precios y stock'}</p></div>{isAdmin&&<button className="button tiny" onClick={()=>setModal('more')}><Ellipsis size={16}/> Acciones{selectedIds.length>0?` (${selectedIds.length})`:''}</button>}</div>
          <div className="table-wrap"><table><thead><tr>{isAdmin&&<th className="check-cell"><input type="checkbox" aria-label="Seleccionar todos los productos de esta página" checked={pageProducts.length>0&&pageProducts.every(p=>selectedIds.includes(p.id))} onChange={event=>setSelectedIds(ids=>event.target.checked?[...new Set([...ids,...pageProducts.map(p=>p.id)])]:ids.filter(id=>!pageProducts.some(p=>p.id===id)))}/></th>}<th>PRODUCTO</th><th>CATEGORÍA</th>{isAdmin&&<th>ESTADO</th>}<th>STOCK</th><th>PRECIO</th><th>PROVEEDOR</th><th>VENCIMIENTO</th>{isAdmin&&<th></th>}</tr></thead><tbody>{pageProducts.map(p=><tr key={p.id}>{isAdmin&&<td><input type="checkbox" aria-label={`Seleccionar ${p.name}`} checked={selectedIds.includes(p.id)} onChange={event=>setSelectedIds(ids=>event.target.checked?[...ids,p.id]:ids.filter(id=>id!==p.id))}/></td>}<td>{isAdmin?<button className="product-cell" onClick={()=>openProduct(p)}><span className="product-thumb"><Package size={17}/></span><span><b>{p.name}</b><small>{p.sku}</small></span></button>:<div className="product-cell"><span className="product-thumb"><Package size={17}/></span><span><b>{p.name}</b><small>{p.sku}</small></span></div>}</td><td><span className="category-chip" style={{'--chip':p.category_color||'#64748b'}}>{p.category_name||'Sin categoría'}</span></td>{isAdmin&&<td><button className={`switch ${p.active?'on':''}`} aria-label={`Cambiar estado de ${p.name}`} aria-pressed={Boolean(p.active)} onClick={async()=>{try{await api(`/products/${p.id}`,{method:'PATCH',body:JSON.stringify({active:p.active?0:1})});await refresh()}catch(e){notify(e.message)}}}><i/></button></td>}<td><b className={p.stock<=p.stock_alert?'stock-low':''}>{p.stock} u</b><small className="cell-sub">Alerta: {p.stock_alert} u</small></td><td><b>{money(p.price)}</b></td><td className="muted">{p.supplier_name||'Sin proveedor'}</td><td>{p.expiry_status!=='none'?<><span className={`stock-state ${p.expiry_status==='expired'?'out':p.expiry_status==='expiring'?'low':'ok'}`}>{expiryLabel(p.expiry_status)}</span><small className="cell-sub">{p.expires_on||p.variants?.find(v=>v.expiry_status!=='none')?.expires_on||''}</small></>:'—'}</td>{isAdmin&&<td><button className="icon-button row-menu" onClick={()=>openProduct(p)} aria-label={`Editar ${p.name}`}><Ellipsis size={18}/></button></td>}</tr>)}</tbody></table>{filtered.length===0&&<div className="empty-state"><Package size={25}/><b>No encontramos productos</b><span>Probá cambiar los filtros o la búsqueda.</span></div>}</div>
          <div className="table-footer"><span>Mostrando <b>{filtered.length?((pageNumber-1)*pageSize+1):0}–{Math.min(pageNumber*pageSize,filtered.length)}</b> de <b>{filtered.length}</b> productos</span><div><button onClick={()=>setPageNumber(n=>Math.max(1,n-1))} disabled={pageNumber<=1}>Atrás</button><span className="current-page">{pageNumber} / {pageCount}</span><button onClick={()=>setPageNumber(n=>Math.min(pageCount,n+1))} disabled={pageNumber>=pageCount}>Siguiente</button></div></div></section>
        </>}
        {page==='Punto de venta'&&<AttendantPOS products={products} customers={customers} customerId={customerId} setCustomerId={setCustomerId} cart={cart} setCart={setCart} addCart={addCart} openPayment={()=>setModal('payment')} notify={notify} exit={()=>setPage('Productos')} cashier={data.user.name}/>}
        {page==='Compras'&&<Purchases key={purchaseRevision} notify={notify} open={()=>setModal('purchase')}/>}
        {page==='Reportes'&&<Reports products={products} notify={notify} openSales={()=>setPage('Historial de ventas')}/>}
        {page==='Historial de ventas'&&<SalesHistory customers={customers} notify={notify} isAdmin={isAdmin}/>}
        {page==='Historial de caja'&&<CashHistory notify={notify}/>}
        {page==='Clientes'&&<Customers notify={notify} refresh={refresh} customers={customers}/>}
        {page==='Usuarios'&&isAdmin&&<UsersManagement notify={notify}/>}
        {page==='Configuración'&&isAdmin&&<SettingsManagement settings={data.tenant} expiryDays={data.expiry_alert_days} saved={async()=>{await refresh();notify('Configuración guardada.')}}/>}
        {page==='Inventario'&&<Inventory products={products} onEdit={openProduct} expiryAlertDays={data.expiry_alert_days}/>}
        {!['Productos','Inventario','Punto de venta','Compras','Reportes','Historial de ventas','Historial de caja','Clientes','Usuarios','Configuración'].includes(page)&&<div className="panel coming-soon"><div className="coming-icon"><Store size={23}/></div><h2>{page}</h2><p>Esta sección forma parte del plan de trabajo.</p><button className="button secondary" onClick={()=>setPage('Productos')}>Volver a productos</button></div>}
      </div>
    </main>
    {modal==='product'&&<ProductModal product={editing} categories={categories} suppliers={suppliers} products={products} refresh={refresh} close={()=>setModal('')} saved={async msg=>{setModal('');await refresh();notify(msg)}} />}
    {['category','supplier'].includes(modal)&&<EntityManagerModal type={modal} close={()=>setModal('')} notify={notify} refresh={refresh}/>}
    {modal==='more'&&<div className="modal-backdrop" onMouseDown={()=>setModal('')}><div className="dropdown-modal" onMouseDown={e=>e.stopPropagation()}>{selectedIds.length>0&&<><div className="dropdown-label">{selectedIds.length} seleccionados</div><button onClick={()=>setBulkStatus(true)}><Check size={16}/> Activar seleccionados</button><button onClick={()=>setBulkStatus(false)}><X size={16}/> Desactivar seleccionados</button><div className="dropdown-divider"/></>}<button onClick={()=>setModal('category')}><Tag size={16}/> Gestionar categorías</button><button onClick={()=>setModal('supplier')}><Truck size={16}/> Gestionar proveedores</button><button onClick={exportProducts}><ArrowDownToLine size={16}/> Exportar catálogo CSV</button></div></div>}
    {modal==='filters'&&<ProductFiltersModal categories={categories} value={filters} close={()=>setModal('')} apply={value=>{setFilters(value);setModal('')}}/>}
    {modal==='notifications'&&<NotificationsModal products={products} cash={data.cash} close={()=>setModal('')} openInventory={()=>{setPage('Inventario');setModal('')}} openCash={()=>setModal('open-cash')}/>}
    {modal==='help'&&<HelpModal close={()=>setModal('')} navigate={destination=>{setPage(destination);setModal('')}}/>}
    {modal==='purchase'&&<PurchaseModal products={products} close={()=>setModal('')} saved={async()=>{setModal('');await refresh();setPurchaseRevision(value=>value+1);notify('Compra registrada y stock actualizado.')}}/>}
    {modal==='open-cash'&&<CashModal close={()=>setModal('')} saved={async()=>{setModal('');await refresh();notify('Caja abierta.')}}/>}
    {modal==='cash'&&<CashManager cash={data.cash} close={()=>setModal('')} saved={async message=>{setModal('');await refresh();notify(message)}}/>}
    {modal==='payment'&&<PaymentModal total={roundMoney(cart.reduce((sum,item)=>sum+roundMoney(item.price*item.quantity),0))} close={()=>setModal('')} submit={finishSale}/>}
    {modal==='ticket'&&ticket&&<TicketModal sale={ticket} close={()=>setModal('')} tenantName={data.tenant.name}/>}
    {toast&&<div className="toast"><Check size={16}/>{toast}</div>}
  </div>
}

function ProductModal({product,categories,suppliers,products,refresh,close,saved}){
  const [form,setForm]=useState({name:product?.name||'',sku:product?.sku||'',description:product?.description||'',category_id:product?.category_id||categories[0]?.id||'',supplier_id:product?.supplier_id||'',unit:product?.unit||'unitario',cost:product?.cost??'',price:product?.price??'',tax_rate:product?.tax_rate??21,tax_included:product?.tax_included??1,stock:product?.stock??0,stock_alert:product?.stock_alert??5,active:product?.active??1,expires_on:product?.expires_on||''});
  const [variants,setVariants]=useState(product?.variants||[]),[error,setError]=useState(''),[entity,setEntity]=useState('');const change=(k,v)=>setForm(f=>({...f,[k]:v}));
  const createEntity=async name=>{const path=entity==='category'?'/categories':'/suppliers';const created=await api(path,{method:'POST',body:JSON.stringify({name})});await refresh();if(entity==='category')change('category_id',created.id);else change('supplier_id',created.id);setEntity('');};
  const submit=async e=>{e.preventDefault();const validation=skuError(form.sku,variants,products,product?.id);if(validation){setError(validation);return}try{await api(product?`/products/${product.id}`:'/products',{method:product?'PATCH':'POST',body:JSON.stringify({...form,stock:variants.length?0:form.stock,variants})});await saved(product?'Producto actualizado.':'Producto creado correctamente.')}catch(e){setError(e.message)}};
  return <div className="modal-backdrop" onMouseDown={close}><form className="modal product-modal" onSubmit={submit} onMouseDown={e=>e.stopPropagation()}><div className="modal-header"><div><div className="eyebrow">CATÁLOGO</div><h2>{product?'Editar producto':'Nuevo producto'}</h2><p>Completá la información para agregarlo a tu inventario</p></div><button type="button" className="icon-button" onClick={close}><X size={20}/></button></div><div className="modal-body">
    <section className="form-section"><div className="section-title"><div className="section-number">1</div><div><b>Identificación</b><small>Nombre, código y clasificación del producto</small></div></div><div className="form-grid"><label className="span-2">Nombre del producto *<input autoFocus value={form.name} onChange={e=>change('name',e.target.value)} placeholder="Ej.: Alfajor de chocolate" required/></label><label>Código / SKU *<div className="input-with-action"><input value={form.sku} onChange={e=>change('sku',e.target.value)} placeholder="Código único" required/><button type="button" className="icon-button" title="Generar código" onClick={()=>change('sku',String(Date.now()).slice(-10))}><Activity size={17}/></button></div></label><label>Tipo de unidad *<select value={form.unit} onChange={e=>change('unit',e.target.value)}><option value="unitario">Unitario</option><option value="kg">Kilogramo</option><option value="g">Gramo</option><option value="l">Litro</option><option value="ml">Mililitro</option><option value="pack">Pack</option></select></label><label className="span-2">Descripción<textarea rows="2" value={form.description} onChange={e=>change('description',e.target.value)} placeholder="Descripción del producto (opcional)"/></label><label>Categoría *<div className="input-with-action"><select value={form.category_id} onChange={e=>change('category_id',e.target.value)} required><option value="">Seleccioná categoría</option>{categories.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select><button className="icon-button" type="button" title="Crear categoría" onClick={()=>setEntity('category')}><Settings size={16}/></button></div></label><label>Proveedor<div className="input-with-action"><select value={form.supplier_id} onChange={e=>change('supplier_id',e.target.value)}><option value="">Sin proveedor</option>{suppliers.map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</select><button className="icon-button" type="button" title="Crear proveedor" onClick={()=>setEntity('supplier')}><Settings size={16}/></button></div></label></div></section>
    <section className="form-section"><div className="section-title"><div className="section-number">2</div><div><b>Precios e impuestos</b><small>El precio final es el importe que se cobra en POS</small></div></div><div className="form-grid"><label className="toggle-label span-2"><span><b>El precio final incluye IVA</b><small>Dato informativo para ayudar a calcular el precio final.</small></span><button type="button" className={`switch ${form.tax_included?'on':''}`} onClick={()=>change('tax_included',form.tax_included?0:1)}><i/></button></label><div className="tax-note span-2">El POS, el ticket y los reportes usan el precio final guardado. El servidor no vuelve a sumar IVA.</div><label>IVA de referencia (%)<input type="number" min="0" step="0.1" value={form.tax_rate} onChange={e=>change('tax_rate',e.target.value)}/></label><label>Costo por unidad<input type="number" min="0" step="0.01" value={form.cost} onChange={e=>change('cost',e.target.value)} placeholder="0,00"/></label><label>Precio sin IVA<input type="number" min="0" step="0.01" value={form.tax_included?Math.round((Number(form.price)||0)/(1+(Number(form.tax_rate)||0)/100)*100)/100:form.price} onChange={e=>change('price',form.tax_included?Number(e.target.value)*(1+(Number(form.tax_rate)||0)/100):e.target.value)} placeholder="0,00"/></label><label>Precio final cobrado *<input type="number" min="0" step="0.01" value={form.price} onChange={e=>change('price',e.target.value)} placeholder="0,00" required/></label></div></section>
    <section className="form-section"><div className="section-title"><div className="section-number">3</div><div><b>Variantes / talles</b><small>Separá el stock por color, tamaño o presentación</small></div></div><div className="variant-list">{variants.map((variant,index)=><div className="variant-row" key={variant.id||index}><input aria-label="Nombre de variante" value={variant.name} onChange={e=>setVariants(items=>items.map((item,i)=>i===index?{...item,name:e.target.value}:item))} placeholder="Ej.: Negro · 250 ml"/><input aria-label="Código de variante" value={variant.sku||''} onChange={e=>setVariants(items=>items.map((item,i)=>i===index?{...item,sku:e.target.value}:item))} placeholder="SKU opcional"/><input aria-label="Stock de variante" type="number" min="0" step="0.01" value={variant.stock} onChange={e=>setVariants(items=>items.map((item,i)=>i===index?{...item,stock:e.target.value}:item))}/><input aria-label={`Vencimiento de ${variant.name||'variante'}`} title="Vencimiento de la variante" type="date" value={variant.expires_on||''} onChange={e=>setVariants(items=>items.map((item,i)=>i===index?{...item,expires_on:e.target.value}:item))}/><button type="button" className="icon-button" aria-label="Quitar variante" onClick={()=>{setError('');if(Number(variant.stock)>0){setError(`No se puede quitar “${variant.name||'esta variante'}” porque tiene ${variant.stock} unidades. Reasigná esas unidades a otra variante y guardá, o corregí el stock a cero antes de eliminarla.`);return}setVariants(items=>items.filter((_,i)=>i!==index))}}><X size={16}/></button></div>)}{variants.length===0&&<div className="variant-empty">Sin variantes. El stock se controla desde el campo principal.</div>}<div className="variant-actions"><span>{variants.length?`Stock total de variantes: ${variants.reduce((sum,v)=>sum+Number(v.stock||0),0)} u`:''}</span><button type="button" className="button secondary" onClick={()=>{if(!variants.length)setVariants([{name:'',sku:'',stock:form.stock||0}]);else setVariants(items=>[...items,{name:'',sku:'',stock:0}])}}><Plus size={15}/> Agregar variante</button></div></div></section>
    <section className="form-section"><div className="section-title"><div className="section-number">4</div><div><b>Stock y estado</b><small>Inventario disponible y aviso de reposición</small></div></div><div className="form-grid"><label>Stock actual (unidades) *<input type="number" min="0" step="0.01" value={variants.length?variants.reduce((sum,v)=>sum+Number(v.stock||0),0):form.stock} readOnly={variants.length>0} onChange={e=>change('stock',e.target.value)} required/></label><label>Alerta de stock<input type="number" min="0" step="1" value={form.stock_alert} onChange={e=>change('stock_alert',e.target.value)}/></label><label>{variants.length?'Vencimiento por variante':'Vencimiento'}{variants.length?<span className="field-hint">Ingresalo en cada variante; si no corresponde, dejalo vacío.</span>:null}{variants.length?null:<input type="date" value={form.expires_on||''} onChange={e=>change('expires_on',e.target.value)}/>}</label><label className="toggle-label"><span><b>Producto activo</b><small>Visible en el punto de venta</small></span><button type="button" className={`switch ${form.active?'on':''}`} onClick={()=>change('active',form.active?0:1)}><i/></button></label></div></section>
    {error&&<div className="form-error">{error}</div>}</div><div className="modal-footer"><button type="button" className="button secondary" onClick={close}>Cancelar</button><button className="button primary" type="submit"><Check size={16}/>{product?'Guardar cambios':'Crear producto'}</button></div></form>{entity&&<EntityModal type={entity} close={()=>setEntity('')} saved={createEntity}/>}</div>
}

function AttendantPOS({products,customers,customerId,setCustomerId,cart,setCart,addCart,openPayment,notify,exit,cashier}){
  const[query,setQuery]=useState('');
  const total=roundMoney(cart.reduce((sum,item)=>sum+roundMoney(Number(item.price)*Number(item.quantity)),0));
  const matching=products.filter(product=>product.active&&(`${product.name} ${product.sku}`.toLowerCase().includes(query.trim().toLowerCase())||product.variants?.some(variant=>`${variant.name} ${variant.sku||''}`.toLowerCase().includes(query.trim().toLowerCase()))));
  const addMatched=()=>{
    const code=query.trim().toLowerCase();
    const variantMatch=products.filter(product=>product.active).flatMap(product=>(product.variants||[]).map(variant=>({product,variant}))).find(({variant})=>variant.sku?.toLowerCase()===code);
    const product=products.find(item=>item.active&&(item.sku.toLowerCase()===code||item.name.toLowerCase()===code));
    if(variantMatch){if(variantMatch.variant.expiry_status==='expired'){notify(`La variante está vencida (${variantMatch.variant.expires_on}) y no se puede vender.`);return}if(variantMatch.variant.stock<=0){notify('La variante no tiene stock.');return}addCart(variantMatch.product,variantMatch.variant);setQuery('');return}
    if(product){if(product.variants?.length){notify('Elegí una variante en los resultados.');return}if(product.expiry_status==='expired'){notify(`El producto está vencido (${product.expires_on}) y no se puede vender.`);return}if(product.stock<=0){notify('El producto no tiene stock.');return}addCart(product);setQuery('');return}
    notify('No encontramos un producto con ese nombre o código.');
  };
  const currentQty=item=>cart.filter(row=>row.key===item.key).reduce((sum,row)=>sum+row.quantity,0);
  const changeQty=(item,delta)=>{if(delta>0&&currentQty(item)>=item.available){notify(`Stock insuficiente. Disponible: ${item.available} u.`);return}setCart(rows=>rows.map(row=>row.key===item.key?{...row,quantity:Math.max(1,row.quantity+delta)}:row))};
  return <div className="pos-layout"><section className="panel pos-left"><div className="panel-heading"><div><h2>Buscar producto</h2><p>Escaneá el código de barras o escribí el nombre</p></div><span className="cashier-chip">Atiende {cashier}</span></div><div className="searchbox pos-search"><Search size={18}/><input autoFocus value={query} onChange={event=>setQuery(event.target.value)} onKeyDown={event=>{if(event.key==='Enter'){event.preventDefault();addMatched()}}} placeholder="Buscar o escanear código…"/><button className="button secondary" type="button" onClick={addMatched}>Agregar</button></div>{query&&<div className="pos-results">{matching.length?matching.slice(0,7).map(product=><div className="pos-result" key={product.id}><button className="pos-result-main" type="button" disabled={!product.variants?.length&&product.expiry_status==='expired'} onClick={()=>{if(product.variants?.length){notify('Este producto tiene variantes. Elegí una opción debajo.');return}if(product.stock<=0){notify('El producto no tiene stock.');return}addCart(product);setQuery('')}}><span className="product-thumb"><Package size={16}/></span><span><b>{product.name}</b><small>{product.sku} · {product.stock} u disponibles{product.expiry_status==='expired'?` · Vencido ${product.expires_on}`:product.expiry_status==='expiring'?` · Vence ${product.expires_on}`:''}</small></span><strong>{money(product.price)}</strong></button>{product.variants?.length>0&&<div className="pos-variant-options">{product.variants.map(variant=><button key={variant.id} type="button" disabled={variant.stock<=0||variant.expiry_status==='expired'} onClick={()=>{addCart(product,variant);setQuery('')}}>{variant.name} <small>{variant.expiry_status==='expired'?`Vencida ${variant.expires_on}`:`${variant.stock} u${variant.expiry_status==='expiring'?` · vence ${variant.expires_on}`:''}`}</small></button>)}</div>}</div>):<div className="pos-no-results">No hay productos que coincidan con “{query}”.</div>}</div>}
    <div className="cart-heading"><div><h2>Carrito</h2><p>{cart.length?`${cart.length} ${cart.length===1?'producto':'productos'}`:'El carrito está vacío'}</p></div><button type="button" className="button secondary" disabled={!cart.length} onClick={()=>setCart([])}>Vaciar</button></div><div className="cart-items">{cart.length?cart.map(item=><div className="cart-item" key={item.key}><div><b>{item.name}</b><small>{item.sku}</small></div><div className="qty-control"><button type="button" aria-label="Restar unidad" onClick={()=>changeQty(item,-1)}>−</button><b>{item.quantity}</b><button type="button" aria-label="Sumar unidad" onClick={()=>changeQty(item,1)}>+</button></div><strong>{money(item.price*item.quantity)}</strong><button type="button" className="icon-button" aria-label="Quitar producto" onClick={()=>setCart(rows=>rows.filter(row=>row.key!==item.key))}><X size={16}/></button></div>):<div className="cart-empty"><ShoppingCart size={34}/><b>Carrito vacío</b><span>Buscá productos para agregarlos a la venta</span></div>}</div>
  </section><aside className="panel pos-summary"><div className="pos-summary-top"><span className="eyebrow">PUNTO DE VENTA</span><button className="icon-button" aria-label="Volver al panel" onClick={exit}><X size={18}/></button></div><label className="customer-picker">Cliente<select value={customerId} onChange={event=>setCustomerId(event.target.value)}><option value="">Consumidor Final</option>{customers.map(customer=><option key={customer.id} value={customer.id}>{customer.name}</option>)}</select></label><div className="summary-title"><h2>Resumen</h2><span>{cart.reduce((sum,item)=>sum+item.quantity,0)} ítems</span></div><div className="summary-row"><span>Subtotal</span><b>{money(total)}</b></div><div className="summary-total"><span>Total</span><b>{money(total)}</b></div><button className="button primary full" disabled={!cart.length} onClick={openPayment}><CreditCard size={17}/> Procesar venta</button><div className="internal-note"><Check size={14}/> Ticket interno · sin factura fiscal</div></aside></div>
}

function EntityModal({type,close,saved}){const[ name,setName]=useState('');const[error,setError]=useState('');const title=type==='category'?'Gestionar categorías':'Gestionar proveedores';const submit=async e=>{e.preventDefault();try{await saved(name)}catch(e){setError(e.message)}};return <div className="modal-backdrop" onMouseDown={close}><form className="modal entity-modal" onSubmit={submit} onMouseDown={e=>e.stopPropagation()}><div className="modal-header"><div><h2>{title}</h2><p>Los datos se guardan para este kiosco.</p></div><button type="button" className="icon-button" onClick={close}><X size={20}/></button></div><div className="modal-body"><label>Nueva {type==='category'?'categoría':'proveedor'}<div className="input-with-action"><input autoFocus value={name} onChange={e=>setName(e.target.value)} placeholder={`Nombre del ${type==='category'?'categoría':'proveedor'}`} required/><button className="button primary" type="submit"><Plus size={16}/> Crear</button></div></label>{error&&<div className="form-error">{error}</div>}</div><div className="modal-footer"><button type="button" className="button secondary" onClick={close}>Cerrar</button></div></form></div>}

function ProductFiltersModal({categories,value,close,apply}){const[filters,setFilters]=useState(value);return <div className="modal-backdrop" onMouseDown={close}><form className="modal compact-modal" onSubmit={event=>{event.preventDefault();apply(filters)}} onMouseDown={event=>event.stopPropagation()}><div className="modal-header"><div><div className="eyebrow">CATÁLOGO</div><h2>Filtrar productos</h2><p>Combiná estado, categoría y disponibilidad.</p></div><button type="button" className="icon-button" onClick={close} aria-label="Cerrar filtros"><X size={20}/></button></div><div className="modal-body filter-form"><label>Estado<select value={filters.status} onChange={event=>setFilters({...filters,status:event.target.value})}><option value="all">Todos</option><option value="active">Activos</option><option value="inactive">Inactivos</option></select></label><label>Categoría<select value={filters.category} onChange={event=>setFilters({...filters,category:event.target.value})}><option value="all">Todas las categorías</option>{categories.map(category=><option key={category.id} value={category.id}>{category.name}</option>)}</select></label><label>Stock<select value={filters.stock} onChange={event=>setFilters({...filters,stock:event.target.value})}><option value="all">Cualquier nivel</option><option value="low">Bajo o en alerta</option><option value="out">Sin stock</option></select></label></div><div className="modal-footer"><button className="button secondary" type="button" onClick={()=>{const reset={status:'all',category:'all',stock:'all'};setFilters(reset);apply(reset)}}>Limpiar filtros</button><button className="button primary" type="submit"><Filter size={15}/> Aplicar filtros</button></div></form></div>}

function NotificationsModal({products,cash,close,openInventory,openCash}){const lowStock=products.filter(product=>product.stock<=product.stock_alert),expiry=expiryRecords(products);return <div className="modal-backdrop" onMouseDown={close}><div className="modal compact-modal" onMouseDown={event=>event.stopPropagation()}><div className="modal-header"><div><div className="eyebrow">AVISOS DEL KIOSCO</div><h2>Notificaciones</h2><p>Alertas de inventario y caja</p></div><button className="icon-button" onClick={close} aria-label="Cerrar notificaciones"><X size={20}/></button></div><div className="modal-body notice-list">{!cash&&<div className="notice-item"><span className="notice-icon warning"><Wallet size={17}/></span><div><b>La caja está cerrada</b><small>Abrila para registrar el efectivo esperado y sus movimientos.</small></div><button className="button tiny" onClick={openCash}>Abrir caja</button></div>}{lowStock.map(product=><div className="notice-item" key={`stock-${product.id}`}><span className="notice-icon"><Package size={17}/></span><div><b>{product.name}</b><small>{product.stock===0?'Sin stock':`${product.stock} u disponibles · alerta en ${product.stock_alert} u`}</small></div><button className="button tiny" onClick={openInventory}>Ver inventario</button></div>)}{expiry.map(item=><div className="notice-item" key={`expiry-${item.id}`}><span className={`notice-icon ${item.status==='expired'?'warning':''}`}><Package size={17}/></span><div><b>{item.name}</b><small>{item.status==='expired'?'Vencido':'Próximo a vencer'} · {item.expires_on}{item.status==='expiring'?` · en ${item.days} día(s)`:''}</small></div><button className="button tiny" onClick={openInventory}>Ver inventario</button></div>)}{!lowStock.length&&!expiry.length&&cash&&<div className="notice-empty"><Check size={20}/><b>Todo al día</b><span>No hay alertas de stock ni de vencimiento.</span></div>}</div><div className="modal-footer"><button className="button secondary" onClick={close}>Cerrar</button></div></div></div>}

function HelpModal({close,navigate}){return <div className="modal-backdrop" onMouseDown={close}><div className="modal compact-modal" onMouseDown={event=>event.stopPropagation()}><div className="modal-header"><div><div className="eyebrow">AYUDA RÁPIDA</div><h2>¿Qué querés hacer?</h2><p>Elegí una sección para abrirla.</p></div><button className="icon-button" onClick={close} aria-label="Cerrar ayuda"><X size={20}/></button></div><div className="modal-body help-links"><button onClick={()=>navigate('Productos')}><Package size={17}/> Crear o editar productos</button><button onClick={()=>navigate('Compras')}><ShoppingBag size={17}/> Ingresar mercadería</button><button onClick={()=>navigate('Punto de venta')}><ShoppingCart size={17}/> Registrar una venta</button><button onClick={()=>navigate('Clientes')}><Users size={17}/> Administrar clientes</button><button onClick={()=>navigate('Inventario')}><Archive size={17}/> Revisar el stock</button></div><div className="modal-footer"><button className="button secondary" onClick={close}>Cerrar</button></div></div></div>}

function Purchases({notify,open}){const[rows,setRows]=useState([]);useEffect(()=>{api('/purchases').then(setRows).catch(e=>notify(e.message))},[]);return <section className="panel table-panel"><div className="panel-heading"><div><h2>Historial de compras</h2><p>Consultá ingresos de mercadería registrados</p></div><button className="button secondary" onClick={open}><Plus size={16}/> Nueva compra</button></div><div className="table-wrap"><table><thead><tr><th>PRODUCTO</th><th>VARIANTE</th><th>FECHA</th><th>CANTIDAD</th><th>COSTO UNITARIO</th><th>SUBTOTAL</th></tr></thead><tbody>{rows.map(r=><tr key={r.id}><td><b>{r.product_name}</b></td><td>{r.variant_name||'—'}</td><td>{new Date(r.created_at+'Z').toLocaleString('es-AR')}</td><td>{r.quantity}</td><td>{money(r.unit_cost)}</td><td><b>{money(r.subtotal)}</b></td></tr>)}</tbody></table>{!rows.length&&<div className="empty-state"><ShoppingBag size={25}/><b>Todavía no hay compras</b><span>Registrá la primera entrada de mercadería.</span><button className="button primary" onClick={open}>Nueva compra</button></div>}</div></section>}
function PurchaseModal({products,close,saved}){const[f,setF]=useState({product_id:'',variant_id:'',quantity:1,unit_cost:0,expires_on:''}),[err,setErr]=useState('');const p=products.find(x=>x.id===f.product_id);const submit=async e=>{e.preventDefault();try{await api('/purchases',{method:'POST',body:JSON.stringify(f)});await saved()}catch(e){setErr(e.message)}};return <div className="modal-backdrop" onMouseDown={close}><form className="modal compact-modal" onSubmit={submit} onMouseDown={e=>e.stopPropagation()}><div className="modal-header"><div><div className="eyebrow">INVENTARIO</div><h2>Nueva compra</h2><p>La compra aumentará el stock disponible</p></div><button type="button" className="icon-button" onClick={close}><X size={20}/></button></div><div className="modal-body form-grid"><label className="span-2">Producto<select value={f.product_id} onChange={e=>{const prod=products.find(x=>x.id===e.target.value);setF({...f,product_id:e.target.value,variant_id:'',unit_cost:prod?.cost||0})}} required><option value="">Seleccionar producto</option>{products.map(product=><option value={product.id} key={product.id}>{product.name} · Stock: {product.stock}</option>)}</select></label>{Boolean(p?.variants?.length)&&<label className="span-2">Variante *<select value={f.variant_id} onChange={e=>setF({...f,variant_id:e.target.value})} required><option value="">Seleccionar variante que recibió la mercadería</option>{p.variants.map(variant=><option value={variant.id} key={variant.id}>{variant.name} · Stock: {variant.stock}</option>)}</select></label>}<label>Cantidad<input type="number" min="0.01" step="0.01" value={f.quantity} onChange={e=>setF({...f,quantity:e.target.value})} required/></label><label>Costo unitario<input type="number" min="0" step="0.01" value={f.unit_cost} onChange={e=>setF({...f,unit_cost:e.target.value})} required/></label><label className="span-2">Vencimiento de esta compra (opcional)<input type="date" value={f.expires_on} onChange={e=>setF({...f,expires_on:e.target.value})}/><small className="field-hint">Las alertas usan la fecha vigente del producto o variante, no el historial de esta compra.</small></label><div className="purchase-total span-2"><span>Subtotal</span><b>{money(Number(f.quantity)*Number(f.unit_cost))}</b></div>{err&&<div className="form-error span-2">{err}</div>}</div><div className="modal-footer"><button type="button" className="button secondary" onClick={close}>Cancelar</button><button className="button primary"><Check size={16}/> Registrar compra</button></div></form></div>}
function CashModal({close,saved}){const[amount,setAmount]=useState(''),[error,setError]=useState('');const submit=async e=>{e.preventDefault();try{await api('/cash/open',{method:'POST',body:JSON.stringify({amount})});await saved()}catch(e){setError(e.message)}};return <div className="modal-backdrop" onMouseDown={close}><form className="modal compact-modal" onSubmit={submit} onMouseDown={e=>e.stopPropagation()}><div className="modal-header"><div><h2>Abrir caja</h2><p>Ingresá el efectivo inicial disponible</p></div><button type="button" className="icon-button" onClick={close}><X size={20}/></button></div><div className="modal-body"><label>Efectivo inicial<input autoFocus type="number" min="0" step="0.01" value={amount} onChange={e=>setAmount(e.target.value)} placeholder="0,00" required/></label>{error&&<div className="form-error">{error}</div>}</div><div className="modal-footer"><button type="button" className="button secondary" onClick={close}>Cancelar</button><button className="button primary">Abrir caja</button></div></form></div>}
function CashManager({cash,close,saved}){
  const[info,setInfo]=useState(null),[kind,setKind]=useState('income'),[amount,setAmount]=useState(''),[note,setNote]=useState(''),[counted,setCounted]=useState(''),[error,setError]=useState(''),[closing,setClosing]=useState(false),[movementPage,setMovementPage]=useState(1);
  const load=()=>api(`/cash/${cash.id}/movements?page=${movementPage}&limit=25`).then(setInfo).catch(e=>setError(e.message));useEffect(()=>{load()},[cash.id,movementPage]);
  const movement=async e=>{e.preventDefault();try{await api('/cash/movements',{method:'POST',body:JSON.stringify({kind,amount,note})});setAmount('');setNote('');setError('');await load()}catch(e){setError(e.message)}};
  const submitClose=async e=>{e.preventDefault();try{const result=await api('/cash/close',{method:'POST',body:JSON.stringify({counted_cash:counted})});await saved(`Caja cerrada. Diferencia: ${money(result.difference)}.`)}catch(e){setError(e.message)}};
  return <div className="modal-backdrop" onMouseDown={close}><div className="modal cash-manager" onMouseDown={e=>e.stopPropagation()}><div className="modal-header"><div><div className="eyebrow">SESIÓN DE CAJA</div><h2>Gestionar caja</h2><p>Abierta {new Date(cash.opened_at+'Z').toLocaleString('es-AR')}</p></div><button className="icon-button" onClick={close}><X size={20}/></button></div><div className="modal-body cash-body"><div className="cash-totals"><div><span>Efectivo inicial</span><b>{money(cash.opening_amount)}</b></div><div><span>Efectivo esperado</span><b>{money(info?.expected_cash??cash.expected_cash)}</b></div><div><span>Movimientos</span><b>{info?.total??cash.movement_count??0}</b></div></div><form className="cash-movement-form" onSubmit={movement}><h3>Registrar movimiento</h3><div className="form-grid"><label>Tipo<select value={kind} onChange={e=>setKind(e.target.value)}><option value="income">Ingreso de efectivo</option><option value="expense">Retiro / egreso</option></select></label><label>Importe<input type="number" min="0.01" step="0.01" value={amount} onChange={e=>setAmount(e.target.value)} required/></label><label className="span-2">Motivo<input value={note} onChange={e=>setNote(e.target.value)} placeholder="Ej.: cambio para caja" required/></label></div><button className="button secondary"><Plus size={15}/> Registrar movimiento</button></form><div className="movement-list"><h3>Actividad de la sesión</h3>{info?.movements.length?info.movements.map(m=><div className="movement-row" key={m.id}><div><b>{m.note}</b><small>{m.kind==='sale'?'Venta':m.kind==='sale_void'?'Anulación de venta':m.kind==='purchase'?'Compra':m.kind==='income'?'Ingreso':'Egreso'} · {new Date(m.created_at+'Z').toLocaleString('es-AR')}</small></div><b className={m.amount<0?'negative':''}>{m.amount>0?'+ ':''}{money(m.amount)}</b></div>):<p className="muted">Todavía no hay movimientos de efectivo.</p>}</div>{info?.total_pages>1&&<PageControls page={movementPage} totalPages={info.total_pages} total={info.total} onChange={setMovementPage}/>}{closing&&<form className="close-cash-form" onSubmit={submitClose}><label>Efectivo contado al cierre<input autoFocus type="number" min="0" step="0.01" value={counted} onChange={e=>setCounted(e.target.value)} required/></label><span>Esperado {money(info?.expected_cash??cash.expected_cash)} · Diferencia {money(Number(counted)-(info?.expected_cash??cash.expected_cash))}</span><button className="button primary">Confirmar cierre</button></form>}{error&&<div className="form-error">{error}</div>}</div><div className="modal-footer"><button className="button secondary" onClick={close}>Volver</button>{!closing&&<button className="button primary" onClick={()=>setClosing(true)}>Cerrar y hacer arqueo</button>}</div></div></div>
}
function PaymentModal({total,close,submit}){
  const[payments,setPayments]=useState([{method:'efectivo',amount:total}]),[error,setError]=useState(''),[busy,setBusy]=useState(false);const busyRef=useRef(false);
  const paid=roundMoney(payments.reduce((sum,p)=>sum+Number(p.amount||0),0)),remaining=roundMoney(total-paid),balanced=Math.round(total*100)===Math.round(paid*100);
  const update=(index,key,value)=>setPayments(items=>items.map((item,i)=>i===index?{...item,[key]:value}:item));
  const pay=async e=>{e.preventDefault();if(busyRef.current)return;if(!balanced){setError(`El pago debe coincidir con el total. Diferencia: ${money(Math.abs(remaining))}.`);return}busyRef.current=true;setBusy(true);try{await submit(payments.map(p=>({...p,amount:Number(p.amount)})))}finally{busyRef.current=false;setBusy(false)}};
  return <div className="modal-backdrop" onMouseDown={close}><form className="modal payment-modal" onSubmit={pay} onMouseDown={e=>e.stopPropagation()}><div className="modal-header"><div><div className="eyebrow">COBRO</div><h2>Procesar venta</h2><p>Confirmá el importe y elegí uno o varios medios de pago</p></div><button type="button" className="icon-button" onClick={close}><X size={20}/></button></div><div className="modal-body"><div className="payment-total"><span>Total de la venta</span><b>{money(total)}</b></div><div className="payment-rows">{payments.map((p,i)=><div className="payment-row" key={i}><label>Medio<select value={p.method} onChange={e=>update(i,'method',e.target.value)}><option value="efectivo">Efectivo</option><option value="tarjeta">Tarjeta</option><option value="transferencia">Transferencia</option><option value="qr">QR</option></select></label><label>Importe<input type="number" min="0.01" step="0.01" value={p.amount} onChange={e=>update(i,'amount',e.target.value)} required/></label><button type="button" className="icon-button" aria-label="Quitar medio de pago" disabled={payments.length===1} onClick={()=>setPayments(items=>items.filter((_,index)=>index!==i))}><X size={16}/></button></div>)}</div><button type="button" className="button secondary add-payment" onClick={()=>setPayments(items=>[...items,{method:'tarjeta',amount:Math.max(0,roundMoney(total-paid))}])}><Plus size={15}/> Agregar otro medio de pago</button><div className={`payment-balance ${balanced?'balanced':''}`}><span>{balanced?'Pago completo':remaining>0?'Restante':'Excedente'}</span><b>{money(Math.abs(remaining))}</b></div>{error&&<div className="form-error">{error}</div>}<p className="internal-note"><Check size={14}/> Se genera un ticket interno, sin factura fiscal.</p></div><div className="modal-footer"><button type="button" className="button secondary" onClick={close}>Cancelar</button><button className="button primary" disabled={busy||!balanced}><CreditCard size={16}/>{busy?'Procesando…':'Confirmar venta'}</button></div></form></div>
}
function TicketModal({sale,close,tenantName}){return <div className="modal-backdrop"><div className="modal ticket-modal"><div className="ticket-success"><div className="success-mark"><Check size={24}/></div><h2>¡Venta exitosa!</h2><p>Ticket interno #{sale.ticket_number}</p><div className="ticket-total"><span>Total</span><b>{money(sale.total)}</b></div></div><div className="receipt"><div className="receipt-business">{tenantName||'Mi Kiosco'}<small>COMPROBANTE INTERNO</small></div><div className="receipt-line"><span>Fecha</span><b>{new Date(sale.created_at+'Z').toLocaleString('es-AR')}</b></div><div className="receipt-line"><span>Cliente</span><b>{sale.customer?.name||'Consumidor Final'}</b></div><div className="receipt-divider"/><div className="receipt-items">{sale.items?.map((item,i)=><div className="receipt-item" key={i}><span>{item.quantity} × {item.product_name}<small>{item.sku}</small></span><b>{money(item.line_total)}</b></div>)}</div><div className="receipt-divider"/><div className="receipt-total"><span>TOTAL</span><b>{money(sale.total)}</b></div><div className="receipt-payments">{sale.payments?.map((payment,i)=><div key={i}><span>{payment.method}</span><b>{money(payment.amount)}</b></div>)}</div><p className="receipt-legal">Comprobante interno · No válido como factura fiscal</p></div><div className="ticket-print"><FileText size={24}/><b>¿Querés imprimir el ticket?</b></div><div className="modal-footer"><button className="button secondary" onClick={close}>Finalizar</button><button className="button primary" onClick={()=>window.print()}><FileText size={16}/> Imprimir ticket</button></div></div></div>}
function normalizeTax(value){return String(value||'').toLocaleUpperCase('es-AR').replace(/[^\p{L}\p{N}]/gu,'')}
function Customers({customers,notify,refresh}){
  const[rows,setRows]=useState([]),[search,setSearch]=useState(''),[form,setForm]=useState({name:'',tax_id:'',phone:'',email:''}),[editing,setEditing]=useState(null),[error,setError]=useState(''),[history,setHistory]=useState(null),[includeArchived,setIncludeArchived]=useState(true);
  const load=async()=>{const params=new URLSearchParams({include_archived:String(includeArchived)});if(search.trim())params.set('search',search.trim());setRows(await api(`/customers?${params}`))};
  useEffect(()=>{let live=true;const params=new URLSearchParams({include_archived:String(includeArchived)});if(search.trim())params.set('search',search.trim());api(`/customers?${params}`).then(data=>{if(live)setRows(data)}).catch(e=>{if(live)setError(e.message)});return()=>{live=false}},[search,includeArchived]);
  const reset=()=>{setForm({name:'',tax_id:'',phone:'',email:''});setEditing(null);setError('')};
  const submit=async e=>{e.preventDefault();setError('');try{const normalized=normalizeTax(form.tax_id);if(normalized){const possibleDuplicates=await api(`/customers?include_archived=true&search=${encodeURIComponent(normalized)}`);if(possibleDuplicates.some(c=>c.id!==editing?.id&&normalizeTax(c.tax_id)===normalized)){setError('Ya existe un cliente con ese DNI/CUIT.');return}}await api(editing?`/customers/${editing.id}`:'/customers',{method:editing?'PATCH':'POST',body:JSON.stringify(form)});reset();await Promise.all([load(),refresh()]);notify(editing?'Cliente actualizado.':'Cliente guardado.')}catch(e){setError(e.message)}};
  const edit=c=>{setEditing(c);setForm({name:c.name,tax_id:c.tax_id||'',phone:c.phone||'',email:c.email||''});setError('')};
  const remove=async c=>{const action=Number(c.sales_count)>0?'archivar':'eliminar';if(!window.confirm(`¿Querés ${action} a ${c.name}?`))return;try{const result=await api(`/customers/${c.id}`,{method:'DELETE'});await Promise.all([load(),refresh()]);notify(result.message)}catch(e){notify(e.message)}};
  const toggle=async c=>{try{await api(`/customers/${c.id}/archive`,{method:'PATCH',body:JSON.stringify({active:c.active?0:1})});await Promise.all([load(),refresh()]);notify(c.active?'Cliente archivado.':'Cliente reactivado.')}catch(e){notify(e.message)}};
  const showHistory=async c=>{try{setHistory(await api(`/customers/${c.id}/history`))}catch(e){notify(e.message)}};
  return <div className="customers-layout"><form className="panel customer-form" onSubmit={submit}><h2>{editing?'Editar cliente':'Nuevo cliente'}</h2><p>Asociá clientes a sus ventas y consultá su historial.</p><label>Nombre y apellido *<input value={form.name} onChange={e=>setForm({...form,name:e.target.value})} required maxLength={150}/></label><label>CUIT / DNI<input value={form.tax_id} onChange={e=>setForm({...form,tax_id:e.target.value})} maxLength={40}/></label><label>Teléfono<input value={form.phone} onChange={e=>setForm({...form,phone:e.target.value})} maxLength={40}/></label><label>Email<input type="email" value={form.email} onChange={e=>setForm({...form,email:e.target.value})} maxLength={254}/></label>{error&&<div className="form-error">{error}</div>}<div className="customer-form-actions"><button className="button primary"><Plus size={15}/>{editing?'Guardar cambios':'Guardar cliente'}</button>{editing&&<button type="button" className="button secondary" onClick={reset}>Cancelar</button>}</div></form><section className="panel table-panel customer-list"><div className="panel-heading customer-heading"><div><h2>Clientes</h2><p>{rows.length} registrados{includeArchived?' (incluye archivados)':''}</p></div><label className="customer-archived"><input type="checkbox" checked={includeArchived} onChange={e=>setIncludeArchived(e.target.checked)}/> Mostrar archivados</label></div><div className="customer-search"><Search size={16}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Buscar por nombre, DNI/CUIT, teléfono o email"/></div><div className="table-wrap"><table><thead><tr><th>NOMBRE</th><th>DNI / CUIT</th><th>TELÉFONO</th><th>EMAIL</th><th>VENTAS</th><th>TOTAL</th><th>ESTADO</th><th>ACCIONES</th></tr></thead><tbody>{rows.map(c=><tr key={c.id} className={!c.active?'archived-row':''}><td><b>{c.name}</b></td><td>{c.tax_id||'—'}</td><td>{c.phone||'—'}</td><td>{c.email||'—'}</td><td>{c.sales_count}</td><td>{money(c.total_purchased)}</td><td>{c.active?'Activo':'Archivado'}</td><td><div className="row-actions"><button className="button tiny" onClick={()=>showHistory(c)}>Historial</button><button className="button tiny" onClick={()=>edit(c)}>Editar</button>{c.active?<button className="button tiny danger" onClick={()=>remove(c)}>{Number(c.sales_count)>0?'Archivar':'Eliminar'}</button>:<button className="button tiny" onClick={()=>toggle(c)}>Reactivar</button>}</div></td></tr>)}</tbody></table>{!rows.length&&<div className="empty-state"><Users size={25}/><b>No encontramos clientes</b><span>Probá cambiar la búsqueda o agregá un cliente.</span></div>}</div></section>{history&&<CustomerHistoryModal data={history} close={()=>setHistory(null)}/>}</div>
}
function CustomerHistoryModal({data,close}){const{customer,summary,sales}=data;return <div className="modal-backdrop" onMouseDown={close}><div className="modal customer-history-modal" onMouseDown={e=>e.stopPropagation()}><div className="modal-header"><div><h2>Historial de {customer.name}</h2><p>{customer.tax_id||customer.email||customer.phone||'Cliente'}</p></div><button className="icon-button" onClick={close}><X size={20}/></button></div><div className="modal-body"><div className="customer-history-summary"><div><span>Compras</span><b>{summary.sales_count}</b></div><div><span>Total</span><b>{money(summary.total_purchased)}</b></div><div><span>Última operación</span><b>{displayDate(summary.last_sale_at)}</b></div></div><div className="table-wrap"><table><thead><tr><th>VENTA</th><th>FECHA</th><th>MEDIOS DE PAGO</th><th>ESTADO</th><th>TOTAL</th></tr></thead><tbody>{sales.map(s=><tr key={s.id}><td>#{s.ticket_number}</td><td>{displayDate(s.created_at)}</td><td>{s.payment_methods||'—'}</td><td>{s.status==='completed'?'Completada':s.status}</td><td>{money(s.total)}</td></tr>)}</tbody></table>{!sales.length&&<div className="empty-state">Todavía no hay ventas asociadas.</div>}</div></div><div className="modal-footer"><button className="button secondary" onClick={close}>Cerrar</button></div></div></div>}
function EntityManagerModal({type,close,notify,refresh}){
  const isCategory=type==='category',endpoint=isCategory?'/categories':'/suppliers',label=isCategory?'categoría':'proveedor';
  const[rows,setRows]=useState([]),[search,setSearch]=useState(''),[editing,setEditing]=useState(null),[name,setName]=useState(''),[color,setColor]=useState('#4169f1'),[error,setError]=useState('');
  const load=()=>api(endpoint).then(setRows).catch(e=>setError(e.message));useEffect(()=>{load()},[endpoint]);
  const reset=()=>{setEditing(null);setName('');setColor('#4169f1');setError('')};
  const submit=async e=>{e.preventDefault();setError('');try{await api(editing?`${endpoint}/${editing.id}`:endpoint,{method:editing?'PATCH':'POST',body:JSON.stringify(isCategory?{name,color}:{name})});reset();await Promise.all([load(),refresh()]);notify(`${label[0].toUpperCase()+label.slice(1)} ${editing?'actualizada':'guardada'}.`)}catch(e){setError(e.message)}};
  const edit=row=>{setEditing(row);setName(row.name);if(isCategory)setColor(row.color||'#4169f1');setError('')};
  const remove=async row=>{if(!window.confirm(`¿Eliminar ${label} «${row.name}»?`))return;try{await api(`${endpoint}/${row.id}`,{method:'DELETE'});await Promise.all([load(),refresh()]);notify(`${label[0].toUpperCase()+label.slice(1)} eliminada.`)}catch(e){setError(e.message)}};
  const filtered=rows.filter(row=>row.name.toLocaleLowerCase('es-AR').includes(search.toLocaleLowerCase('es-AR')));
  return <div className="modal-backdrop" onMouseDown={close}><div className="modal entity-manager-modal" onMouseDown={e=>e.stopPropagation()}><div className="modal-header"><div><h2>Gestionar {isCategory?'categorías':'proveedores'}</h2><p>Los registros vinculados se conservan para proteger el historial.</p></div><button className="icon-button" onClick={close}><X size={20}/></button></div><div className="modal-body"><form className="entity-manager-form" onSubmit={submit}><label>{editing?'Editar':'Nueva'} {label}<input autoFocus value={name} onChange={e=>setName(e.target.value)} required maxLength={isCategory?100:150}/></label>{isCategory&&<label>Color<input type="color" value={color} onChange={e=>setColor(e.target.value)}/></label>}<div className="entity-form-actions"><button className="button primary"><Plus size={15}/>{editing?'Guardar cambios':'Crear'}</button>{editing&&<button type="button" className="button secondary" onClick={reset}>Cancelar</button>}</div>{error&&<div className="form-error">{error}</div>}</form><div className="customer-search entity-search"><Search size={16}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder={`Buscar ${isCategory?'categoría':'proveedor'}…`}/></div><div className="entity-list">{filtered.map(row=><div className="entity-row" key={row.id}>{isCategory&&<i style={{background:row.color}}/>}<div><b>{row.name}</b><small>{isCategory?`${row.product_count||0} productos`:`${row.product_count||0} productos · ${row.purchase_count||0} compras`}</small></div><button className="button tiny" onClick={()=>edit(row)}>Editar</button><button className="button tiny danger" title={Number(row.product_count)>0||Number(row.purchase_count)>0?'Hay registros asociados':''} onClick={()=>{if(Number(row.product_count)>0||Number(row.purchase_count)>0){setError(isCategory?`No se puede eliminar: ${row.product_count} producto(s) usan esta categoría.`:`No se puede eliminar: tiene ${row.product_count} producto(s) y ${row.purchase_count} compra(s) asociadas.`);return}remove(row)}}>{Number(row.product_count)>0||Number(row.purchase_count)>0?'En uso':'Eliminar'}</button></div>)}{!filtered.length&&<div className="empty-state">No hay {isCategory?'categorías':'proveedores'} que coincidan.</div>}</div></div><div className="modal-footer"><button className="button secondary" onClick={close}>Cerrar</button></div></div></div>
}
function expiryLabel(status){return status==='expired'?'Vencido':status==='expiring'?'Próximo':status==='ok'?'Vigente':'Sin fecha'}
function expiryRecords(products){return products.flatMap(product=>product.variants?.length?product.variants.filter(v=>v.stock>0&&['expired','expiring'].includes(v.expiry_status)).map(v=>({id:v.id,name:`${product.name} · ${v.name}`,expires_on:v.expires_on,status:v.expiry_status,days:v.expiry_days,product_id:product.id})):product.stock>0&&['expired','expiring'].includes(product.expiry_status)?[{id:product.id,name:product.name,expires_on:product.expires_on,status:product.expiry_status,days:product.expiry_days,product_id:product.id}]:[])}
function Inventory({products,onEdit,expiryAlertDays=30}){
  const[filter,setFilter]=useState('all');const expiring=expiryRecords(products),expired=expiring.filter(x=>x.status==='expired'),near=expiring.filter(x=>x.status==='expiring');
  const rows=products.filter(p=>filter==='low'?p.stock>0&&p.stock<=p.stock_alert:filter==='out'?p.stock===0:filter==='expired'?p.expiry_status==='expired':filter==='expiring'?p.expiry_status==='expiring':true);
  const expiryCell=p=>p.variants?.length?<div className="inventory-expiry-list">{p.variants.map(v=><div key={v.id}><b>{v.name}</b><span>{v.expires_on?<><i className={`expiry-dot ${v.expiry_status}`}/>{v.expires_on} · {v.stock>0?expiryLabel(v.expiry_status):'Sin stock'}</>:'—'}</span></div>)}</div>:p.expires_on?<><span className={`stock-state ${p.expiry_status==='expired'?'out':p.expiry_status==='expiring'?'low':'ok'}`}>{p.stock>0?expiryLabel(p.expiry_status):'Sin stock'}</span><small className="cell-sub">{p.expires_on}</small></>:'—';
  return <><div className="inventory-summary inventory-summary-five"><button className={`inventory-stat ${filter==='all'?'active':''}`} onClick={()=>setFilter('all')}><span>Todos los productos</span><b>{products.length}</b></button><button className={`inventory-stat ${filter==='low'?'active':''}`} onClick={()=>setFilter('low')}><span>Stock bajo</span><b>{products.filter(p=>p.stock>0&&p.stock<=p.stock_alert).length}</b></button><button className={`inventory-stat ${filter==='out'?'active':''}`} onClick={()=>setFilter('out')}><span>Sin stock</span><b>{products.filter(p=>p.stock===0).length}</b></button><button className={`inventory-stat ${filter==='expired'?'active':''}`} onClick={()=>setFilter('expired')}><span>Vencidos</span><b>{expired.length}</b></button><button className={`inventory-stat ${filter==='expiring'?'active':''}`} onClick={()=>setFilter('expiring')}><span>Próximos ({expiryAlertDays} días)</span><b>{near.length}</b></button></div><section className="panel table-panel"><div className="panel-heading"><div><h2>Existencias</h2><p>Alertas de vencimiento calculadas por el servidor; aviso próximo hasta {expiryAlertDays} días.</p></div></div><div className="table-wrap"><table><thead><tr><th>PRODUCTO</th><th>CATEGORÍA</th><th>STOCK ACTUAL</th><th>ALERTA</th><th>VENCIMIENTO</th><th>ESTADO</th><th></th></tr></thead><tbody>{rows.map(p=><tr key={p.id}><td><b>{p.name}</b><small className="cell-sub">{p.sku}</small></td><td>{p.category_name}</td><td><b className={p.stock<=p.stock_alert?'stock-low':''}>{p.stock} u</b></td><td>{p.stock_alert} u</td><td>{expiryCell(p)}</td><td><span className={`stock-state ${p.stock===0?'out':p.stock<=p.stock_alert?'low':'ok'}`}>{p.stock===0?'Sin stock':p.stock<=p.stock_alert?'Reponer':'Disponible'}</span></td><td><button className="button tiny" onClick={()=>onEdit(p)}>Editar</button></td></tr>)}</tbody></table>{!rows.length&&<div className="empty-state"><Archive size={25}/><b>No hay productos en este filtro</b></div>}</div></section></>
}
const displayDate=value=>value?new Date(`${String(value).replace(' ','T')}Z`).toLocaleString('es-AR'):'—';
const methodName={efectivo:'Efectivo',tarjeta:'Tarjeta',transferencia:'Transferencia',qr:'QR'};
function PageControls({page,totalPages,total,onChange}){return <div className="table-footer history-pagination"><span>{total} registros · Página {totalPages?Math.min(page,totalPages):0} de {totalPages}</span><div><button className="button secondary tiny" disabled={page<=1} onClick={()=>onChange(page-1)}>Anterior</button><button className="button secondary tiny" disabled={!totalPages||page>=totalPages} onClick={()=>onChange(page+1)}>Siguiente</button></div></div>}
function SalesHistory({customers,notify,isAdmin}){
  const[draft,setDraft]=useState({from:'',to:'',method:'',customer_id:'',q:''}),[criteria,setCriteria]=useState({from:'',to:'',method:'',customer_id:'',q:''});
  const[result,setResult]=useState({items:[],total:0,page:1,page_size:25,total_pages:0}),[page,setPage]=useState(1),[limit,setLimit]=useState(25),[selected,setSelected]=useState(''),[error,setError]=useState(''),[revision,setRevision]=useState(0);
  useEffect(()=>{const params=new URLSearchParams({page:String(page),limit:String(limit)});for(const[key,value]of Object.entries(criteria))if(value)params.set(key,value);let live=true;setError('');api(`/sales?${params}`).then(data=>{if(live)setResult(data)}).catch(e=>{if(live)setError(e.message)});return()=>{live=false}},[criteria,limit,page,revision]);
  const submit=event=>{event.preventDefault();setPage(1);setCriteria({...draft})};
  return <><form className="panel history-filters" onSubmit={submit}><label>Desde<input type="date" value={draft.from} onChange={e=>setDraft({...draft,from:e.target.value})}/></label><label>Hasta<input type="date" value={draft.to} onChange={e=>setDraft({...draft,to:e.target.value})}/></label><label>Medio de pago<select value={draft.method} onChange={e=>setDraft({...draft,method:e.target.value})}><option value="">Todos</option>{Object.entries(methodName).map(([key,label])=><option key={key} value={key}>{label}</option>)}</select></label><label>Cliente<select value={draft.customer_id} onChange={e=>setDraft({...draft,customer_id:e.target.value})}><option value="">Todos</option>{customers.map(customer=><option key={customer.id} value={customer.id}>{customer.name}</option>)}</select></label><label className="history-search">N.º de venta<input inputMode="numeric" value={draft.q} onChange={e=>setDraft({...draft,q:e.target.value.replace(/[^0-9#]/g,'')})} placeholder="Ej.: 105"/></label><button className="button primary">Aplicar filtros</button><button className="button secondary" type="button" onClick={()=>{const empty={from:'',to:'',method:'',customer_id:'',q:''};setDraft(empty);setCriteria(empty);setPage(1)}}>Limpiar</button></form>
    <section className="panel table-panel"><div className="panel-heading"><div><h2>Ventas</h2><p>{result.total} tickets · Consultas paginadas desde el servidor</p></div><label className="page-size">Por página<select value={limit} onChange={e=>{setLimit(Number(e.target.value));setPage(1)}}><option value="25">25</option><option value="50">50</option><option value="100">100</option></select></label></div><div className="table-wrap"><table className="history-table"><thead><tr><th>VENTA</th><th>FECHA Y HORA</th><th>CLIENTE</th><th>MEDIOS DE PAGO</th><th>ITEMS</th><th>ESTADO</th><th>NETO</th><th></th></tr></thead><tbody>{result.items.map(s=><tr key={s.id}><td><b>#{s.ticket_number}</b></td><td>{displayDate(s.created_at)}</td><td>{s.customer_name||'Consumidor final'}</td><td>{s.payments.map(p=>`${methodName[p.method]||p.method} ${money(p.amount)}`).join(' · ')||'—'}</td><td>{s.item_count} u. / {s.line_count} líneas</td><td><span className={`status-pill ${s.status==='voided'?'closed':''}`}>{s.status==='completed'?'Válida':s.status==='voided'?'Anulada':s.status}</span></td><td><b>{money(s.net_total)}</b>{s.status==='voided'&&<small className="cell-sub">Original {money(s.total)}</small>}</td><td><button className="button tiny" onClick={()=>setSelected(s.id)}>Ver detalle</button></td></tr>)}</tbody></table>{error&&<div className="form-error history-error">{error}</div>}{!error&&!result.items.length&&<div className="empty-state"><FileText size={25}/><b>No hay ventas para estos filtros</b><span>Probá ampliar el período o limpiar los filtros.</span></div>}</div><PageControls page={page} totalPages={result.total_pages} total={result.total} onChange={setPage}/></section>
    {selected&&<SaleDetailModal id={selected} isAdmin={isAdmin} close={()=>setSelected('')} onVoided={()=>{setSelected('');setRevision(value=>value+1);notify('Venta anulada. Se revirtió el stock y los pagos según su medio.')}}/>}
  </>;
}
function SaleDetailModal({id,close,isAdmin,onVoided}){
  const[sale,setSale]=useState(null),[error,setError]=useState(''),[reason,setReason]=useState(''),[confirming,setConfirming]=useState(false),[saving,setSaving]=useState(false);
  useEffect(()=>{let live=true;api(`/sales/${id}`).then(value=>{if(live)setSale(value)}).catch(e=>{if(live)setError(e.message)});return()=>{live=false}},[id]);
  const voidSale=async event=>{event.preventDefault();if(!window.confirm(`¿Anular la venta #${sale.ticket_number}? Se restaurará el stock y se registrará la reversión del pago.`))return;setSaving(true);setError('');try{await api(`/sales/${id}/void`,{method:'POST',body:JSON.stringify({reason})});onVoided()}catch(e){setError(e.message)}finally{setSaving(false)}};
  const stateLabel=sale?.status==='completed'?'Válida':sale?.status==='voided'?'Anulada':sale?.status||'';
  return <div className="modal-backdrop" onMouseDown={close}><div className="modal history-detail-modal" onMouseDown={e=>e.stopPropagation()}><div className="modal-header"><div><div className="eyebrow">HISTORIAL DE VENTAS</div><h2>{sale?`Venta #${sale.ticket_number}`:'Detalle de venta'}</h2><p>{sale?`${displayDate(sale.created_at)} · ${sale.customer?.name||'Consumidor final'} · ${sale.user_name||'Usuario anterior'}`:'Cargando información registrada…'}</p></div><button className="icon-button" aria-label="Cerrar detalle" onClick={close}><X size={20}/></button></div>{sale?<div className="modal-body history-detail-body"><div className="history-status-line"><span className={`status-pill ${sale.status==='voided'?'closed':''}`}>{stateLabel}</span>{sale.status==='voided'&&<span>Anulada {displayDate(sale.voided_at)} por {sale.voided_by_name||'usuario'}</span>}</div><div className="table-wrap"><table className="history-table"><thead><tr><th>PRODUCTO</th><th>VARIANTE</th><th>CANTIDAD</th><th>PRECIO UNITARIO</th><th>SUBTOTAL</th></tr></thead><tbody>{sale.items.map((item,index)=><tr key={`${item.product_id||item.sku}-${index}`}><td><b>{item.variant_name&&item.product_name.endsWith(` · ${item.variant_name}`)?item.product_name.slice(0,-(` · ${item.variant_name}`).length):item.product_name}</b><small className="cell-sub">{item.sku}</small></td><td>{item.variant_name||'—'}</td><td>{item.quantity}</td><td>{money(item.unit_price)}</td><td>{money(item.line_total)}</td></tr>)}</tbody></table></div><div className="history-detail-summary"><div><span>Importe original</span><b>{money(sale.total)}</b></div><div><span>Importe revertido</span><b>{money(sale.refunded_total||0)}</b></div><div><span>Neto</span><b>{money(sale.net_total)}</b></div></div><div className="history-block"><h3>Pagos originales</h3>{sale.payments.map((payment,index)=><div className="history-line" key={`${payment.method}-${index}`}><span>{methodName[payment.method]||payment.method}</span><b>{money(payment.amount)}</b></div>)}</div>{sale.void&&<><div className="history-block"><h3>Reversión registrada</h3><p>{sale.void.reason}</p>{sale.void.payments.map((payment,index)=><div className="history-line" key={`void-${index}`}><span>Reversión · {methodName[payment.method]||payment.method}</span><b>{money(payment.amount)}</b></div>)}</div></> }<div className="history-block"><h3>Relación con caja</h3>{sale.cash_movements.length?sale.cash_movements.map(movement=><div className="history-line" key={movement.id}><span>{movement.note}<small>{displayDate(movement.created_at)} · Sesión {movement.session_id.slice(0,8)}</small></span><b className={movement.amount<0?'negative':''}>{movement.amount>0?'+ ':''}{money(movement.amount)}</b></div>):<p className="muted">Esta venta no tuvo un movimiento de efectivo físico asociado.</p>}{sale.session&&<small className="history-session">Sesión original {displayDate(sale.session.opened_at)} · Estado: {sale.session.status==='open'?'abierta':'cerrada'}</small>}</div>{error&&<div className="form-error">{error}</div>}</div>:<div className="modal-body">{error?<div className="form-error">{error}</div>:<div className="history-loading">Cargando detalle…</div>}</div>}{confirming&&sale?.status==='completed'&&<form className="void-form" onSubmit={voidSale}><label>Motivo de anulación<textarea value={reason} onChange={event=>setReason(event.target.value)} minLength="5" maxLength="500" required placeholder="Explicá brevemente por qué se anula esta venta."/></label><small>Se conservarán el ticket y los pagos originales. El motivo quedará en el historial.</small><div className="void-form-actions"><button type="button" className="button secondary" onClick={()=>setConfirming(false)}>Cancelar</button><button className="button danger" disabled={saving||reason.trim().length<5}>{saving?'Procesando…':'Confirmar anulación'}</button></div></form>}<div className="modal-footer">{isAdmin&&sale?.status==='completed'&&!confirming&&<button className="button danger" onClick={()=>setConfirming(true)}>Anular venta</button>}<button className="button secondary" onClick={close}>Cerrar</button></div></div></div>;
}
function CashHistory({notify}){
  const[draft,setDraft]=useState({from:'',to:''}),[criteria,setCriteria]=useState({from:'',to:''}),[page,setPage]=useState(1),[limit,setLimit]=useState(25),[result,setResult]=useState({items:[],total:0,total_pages:0}),[selected,setSelected]=useState(''),[error,setError]=useState('');
  useEffect(()=>{const params=new URLSearchParams({page:String(page),limit:String(limit)});for(const[k,v]of Object.entries(criteria))if(v)params.set(k,v);let live=true;api(`/cash/sessions?${params}`).then(value=>{if(live)setResult(value)}).catch(e=>{if(live)setError(e.message)});return()=>{live=false}},[criteria,limit,page]);
  return <><form className="panel history-filters compact-history-filters" onSubmit={e=>{e.preventDefault();setPage(1);setCriteria({...draft})}}><label>Sesiones abiertas desde<input type="date" value={draft.from} onChange={e=>setDraft({...draft,from:e.target.value})}/></label><label>Hasta<input type="date" value={draft.to} onChange={e=>setDraft({...draft,to:e.target.value})}/></label><button className="button primary">Aplicar</button><button className="button secondary" type="button" onClick={()=>{setDraft({from:'',to:''});setCriteria({from:'',to:''});setPage(1)}}>Limpiar</button></form>
    <section className="panel table-panel"><div className="panel-heading"><div><h2>Sesiones de caja</h2><p>{result.total} sesiones · efectivo esperado, contado e ingresos/egresos</p></div><label className="page-size">Por página<select value={limit} onChange={e=>{setLimit(Number(e.target.value));setPage(1)}}><option value="25">25</option><option value="50">50</option><option value="100">100</option></select></label></div><div className="table-wrap"><table className="history-table"><thead><tr><th>APERTURA</th><th>MONTO INICIAL</th><th>CIERRE</th><th>ESPERADO</th><th>CONTADO</th><th>DIFERENCIA</th><th>INGRESOS</th><th>EGRESOS</th><th>ESTADO</th><th></th></tr></thead><tbody>{result.items.map(session=><tr key={session.id} className={selected===session.id?'selected-history-row':''}><td>{displayDate(session.opened_at)}</td><td>{money(session.opening_amount)}</td><td>{displayDate(session.closed_at)}</td><td><b>{money(session.expected_cash)}</b></td><td>{session.closing_amount==null?'—':money(session.closing_amount)}</td><td>{session.difference==null?'—':money(session.difference)}</td><td>{money(session.total_income)}</td><td>{money(session.total_expenses)}</td><td><span className={`status-pill ${session.status==='open'?'':'closed'}`}>{session.status==='open'?'Abierta':'Cerrada'}</span></td><td><button className="button tiny" onClick={()=>setSelected(selected===session.id?'':session.id)}>{selected===session.id?'Ocultar':'Movimientos'}</button></td></tr>)}</tbody></table>{error&&<div className="form-error history-error">{error}</div>}{!error&&!result.items.length&&<div className="empty-state"><Wallet size={25}/><b>Todavía no hay sesiones</b><span>Las aperturas y cierres aparecerán acá.</span></div>}</div><PageControls page={page} totalPages={result.total_pages} total={result.total} onChange={setPage}/></section>
    {selected&&<CashSessionDetail id={selected}/>}
  </>;
}
function CashSessionDetail({id}){
  const[page,setPage]=useState(1),[info,setInfo]=useState(null),[error,setError]=useState('');
  useEffect(()=>{let live=true;api(`/cash/${id}/movements?page=${page}&limit=25`).then(value=>{if(live)setInfo(value)}).catch(e=>{if(live)setError(e.message)});return()=>{live=false}},[id,page]);
  return <section className="panel cash-history-detail"><div className="panel-heading"><div><h2>Movimientos de sesión</h2><p>{info?`Apertura ${displayDate(info.session.opened_at)} · efectivo esperado ${money(info.expected_cash)}`:'Cargando sesión…'}</p></div>{info&&<div className="cash-history-totals"><span>Ingresos <b>{money(info.total_income)}</b></span><span>Egresos <b>{money(info.total_expenses)}</b></span></div>}</div>{error?<div className="form-error">{error}</div>:info?<><div className="table-wrap"><table className="history-table"><thead><tr><th>FECHA Y HORA</th><th>TIPO</th><th>CONCEPTO / ORIGEN</th><th>OPERACIÓN</th><th>USUARIO</th><th>IMPORTE</th></tr></thead><tbody>{info.movements.map(movement=><tr key={movement.id}><td>{displayDate(movement.created_at)}</td><td>{movement.kind==='sale'?'Ingreso por venta':movement.kind==='sale_void'?'Reversión de anulación':movement.kind==='purchase'?'Egreso por compra':movement.kind==='income'?'Ingreso manual':'Egreso manual'}</td><td>{movement.note}</td><td>{movement.sale_ticket_number?`Venta #${movement.sale_ticket_number}`:movement.purchase_id?`Compra ${movement.purchase_id.slice(0,8)}`:'—'}</td><td>{movement.user_name||'—'}</td><td><b className={movement.amount<0?'negative':''}>{movement.amount>0?'+ ':''}{money(movement.amount)}</b></td></tr>)}</tbody></table>{!info.movements.length&&<div className="empty-state"><Wallet size={24}/><b>Esta sesión no tiene movimientos</b></div>}</div><PageControls page={page} totalPages={info.total_pages} total={info.total} onChange={setPage}/></>:<div className="history-loading">Cargando movimientos…</div>}</section>;
}
function Reports({products,notify,openSales}){
  const[draft,setDraft]=useState({from:'',to:''}),[criteria,setCriteria]=useState({from:'',to:''}),[result,setResult]=useState(null),[error,setError]=useState('');
  useEffect(()=>{const params=new URLSearchParams();for(const[k,v]of Object.entries(criteria))if(v)params.set(k,v);let live=true;setError('');api(`/reports/sales${params.toString()?`?${params}`:''}`).then(value=>{if(live)setResult(value)}).catch(e=>{if(live)setError(e.message)});return()=>{live=false}},[criteria]);
  return <><form className="panel history-filters compact-history-filters" onSubmit={e=>{e.preventDefault();setCriteria({...draft})}}><label>Desde<input type="date" value={draft.from} onChange={e=>setDraft({...draft,from:e.target.value})}/></label><label>Hasta<input type="date" value={draft.to} onChange={e=>setDraft({...draft,to:e.target.value})}/></label><button className="button primary">Actualizar totales</button><button className="button secondary" type="button" onClick={()=>{setDraft({from:'',to:''});setCriteria({from:'',to:''})}}>Todo el historial</button></form>{error&&<div className="form-error">{error}</div>}
    <div className="stats-grid report-sales-grid"><div className="stat-card"><span>Ventas registradas</span><b>{result?.sale_count??'—'}</b><small>Según el período solicitado</small></div><div className="stat-card"><span>Total vendido</span><b>{money(result?.total_sales)}</b><small>Todos los medios de pago</small></div>{Object.entries(methodName).map(([key,label])=><div className="stat-card" key={key}><span>{label}</span><b>{money(result?.payment_totals?.[key])}</b><small>{key==='efectivo'?'Efectivo físico ingresado':'Pagos registrados'}</small></div>)}</div>
    <div className="stats-grid"><div className="stat-card"><span>Productos en catálogo</span><b>{products.length}</b><small>Productos registrados</small></div><div className="stat-card warning"><span>Stock bajo</span><b>{products.filter(p=>p.stock<=p.stock_alert).length}</b><small>Revisá los niveles de alerta</small></div></div>
    <section className="panel report-history-link"><div><h2>Consultar tickets anteriores</h2><p>El historial permite filtrar por fechas, cliente, pago y número de venta.</p></div><button className="button secondary" onClick={openSales}>Abrir historial de ventas</button></section>
  </>;
}
